#include "stdafx.h"#include "HcdElementBase.h"struct SMDSW_P{#include "PrivateVars/MDSW.h"};class KMDSW : public KHcdElementBase  , protected SMDSW_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _MDSW("MDSW", KMDSW::Create);IHcdElement *KMDSW::Create(){  return new KMDSW;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KMDSW, 6 )void KMDSW::InitParm(){#include "PrivateVars/MDSW.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KMDSW::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KMDSW::StepCalc( SStepCalcParams &params ){  tDigital32 req = 0;  tBool *pMod = &AUTO;  tDigital32 mask = 1;  for( int i=0; i<4; ++i, mask = mask << 1 )  {    if( pMod[i] )      req = mask;  }  if( _prevMDRQO != req )    MDRQO = req;  else    MDRQO = 0;  _prevMDRQO = req;}